        <div class="section-title">
          <span>Source gaps</span>
          <span class="small">evidence risk</span>
        </div>
        <div class="chips">
          <label class="chip"><input type="checkbox" class="gap" data-points="13" data-name="No primary source">No primary source</label>
          <label class="chip"><input type="checkbox" class="gap" data-points="11" data-name="Old or undated sources">Old or undated sources</label>
          <label class="chip"><input type="checkbox" class="gap" data-points="9" data-name="Stats lack year/context">Stats lack year/context</label>
          <label class="chip"><input type="checkbox" class="gap" data-points="10" data-name="Screenshots/examples stale">Screenshots/examples stale</label>
        </div>

        <div class="section-title">
          <span>Date gaps</span>
          <span class="small">timeliness risk</span>
        </div>
        <div class="chips">
          <label class="chip"><input type="checkbox" class="gap" data-points="14" data-name="Missing visible update date">Missing visible update date</label>
          <label class="chip"><input type="checkbox" class="gap" data-points="12" data-name="Time-sensitive claims">Time-sensitive claims</label>
          <label class="chip"><input type="checkbox" class="gap" data-points="12" data-name="Rules/prices/tools may have changed">Rules/prices/tools changed</label>
          <label class="chip"><input type="checkbox" class="gap" data-points="8" data-name="Competitor pages look fresher">Competitors fresher</label>
        </div>

        <div class="section-title">
          <span>FAQ and intent gaps</span>
          <span class="small">search fit</span>
        </div>
        <div class="chips">
          <label class="chip"><input type="checkbox" class="gap" data-points="9" data-name="Missing current-year FAQ">Missing current-year FAQ</label>
          <label class="chip"><input type="checkbox" class="gap" data-points="8" data-name="Reader next steps unclear">Next steps unclear</label>
          <label class="chip"><input type="checkbox" class="gap" data-points="7" data-name="FAQ does not answer objections">Objections unanswered</label>
