        </div>
        <div id="status" class="status" aria-live="polite"></div>
      </div>
    </section>
  </main>

  <script>
    (function () {
      "use strict";

      var els = {
        title: document.getElementById("title"),
        lastDate: document.getElementById("lastDate"),
        topicType: document.getElementById("topicType"),
        notes: document.getElementById("notes"),
        gaps: Array.prototype.slice.call(document.querySelectorAll(".gap")),
        riskLabel: document.getElementById("riskLabel"),
        riskScore: document.getElementById("riskScore"),
        riskBar: document.getElementById("riskBar"),
        reasons: document.getElementById("reasons"),
        brief: document.getElementById("brief"),
        copyBtn: document.getElementById("copyBtn"),
        downloadBtn: document.getElementById("downloadBtn"),
        saveBtn: document.getElementById("saveBtn"),
        clearBtn: document.getElementById("clearBtn"),
        status: document.getElementById("status")
      };

      var storageKey = "freshnessRewriteChecker.v1";

      function monthsOld(dateValue) {
        if (!dateValue) return null;
        var then = new Date(dateValue + "T00:00:00");
        if (isNaN(then.getTime())) return null;
        var now = new Date();
        var years = now.getFullYear() - then.getFullYear();
        var months = now.getMonth() - then.getMonth();
        return Math.max(0, years * 12 + months);
      }

      function topicPoints(type) {
        var map = {
          evergreen: 0,
          software: 17,
          money: 22,
          product: 18,
          news: 25
        };
        return map[type] || 0;
      }

      function topicLabel(type) {
        var map = {
          evergreen: "mostly evergreen",
          software: "software / AI / tools",
          money: "finance / tax / legal / medical / rules",
          product: "pricing / product / vendor",
          news: "news / trend / fast-moving"
        };
        return map[type] || "mostly evergreen";
      }

      function getCheckedGaps() {
        return els.gaps
          .filter(function (box) { return box.checked; })
          .map(function (box) {
            return {
              name: box.getAttribute("data-name") || "Gap",
              points: Number(box.getAttribute("data-points") || 0)
            };
          });
      }

      function classify(score) {
        if (score >= 70) {
          return {
            label: "Rewrite now",
            color: "var(--bad)",
            action: "Full freshness rewrite recommended."
          };
        }
        if (score >= 42) {
          return {
            label: "Review soon",
            color: "var(--watch)",
            action: "Targeted update recommended."
          };
        }
        if (score >= 18) {
          return {
            label: "Light refresh",
            color: "var(--accent)",
            action: "Small update may be enough."
          };
        }
        return {
          label: "Low risk",
          color: "var(--good)",
          action: "No major freshness rewrite needed from these inputs."
        };
      }

      function buildReasons(score, ageMonths, gaps) {
        var reasons = [];
        var type = els.topicType.value;

        if (!els.title.value.trim() && !els.notes.value.trim()) {
          reasons.push("Add a title or notes to get a useful result.");
          return reasons;
        }

        if (ageMonths === null) {
          reasons.push("No update date entered, so the article may look stale to readers.");
        } else if (ageMonths >= 36) {
          reasons.push("The article is about " + ageMonths + " months old.");
        } else if (ageMonths >= 24) {
          reasons.push("The article is over two years old.");
        } else if (ageMonths >= 12) {
          reasons.push("The article is over one year old.");
        }

        if (type !== "evergreen") {
          reasons.push("Topic type is " + topicLabel(type) + ", so freshness matters more.");
        }

        gaps.slice(0, 5).forEach(function (gap) {
          reasons.push(gap.name + " is marked.");
        });

        if (score >= 70) {
          reasons.push("Risk is high enough that small edits may not fix trust or search intent issues.");
        } else if (score >= 42) {
          reasons.push("Risk is moderate, so prioritize the highest-impact outdated sections first.");
        } else if (score >= 18) {
          reasons.push("Risk is present but likely fixable with a focused refresh.");
        } else {
          reasons.push("Few freshness gaps are marked.");
        }

        return reasons;
      }

      function calculate() {
        var title = els.title.value.trim();
        var notes = els.notes.value.trim();
        var age = monthsOld(els.lastDate.value);
        var gaps = getCheckedGaps();
        var score = 0;

        score += topicPoints(els.topicType.value);

        if (age === null) {
          score += title || notes ? 18 : 0;
        } else if (age >= 36) {
          score += 24;
        } else if (age >= 24) {
          score += 19;
        } else if (age >= 18) {
          score += 14;
        } else if (age >= 12) {
          score += 8;
        } else if (age >= 6) {
          score += 4;
        }

        gaps.forEach(function (gap) {
          score += gap.points;
        });

        if (notes.length > 650) score += 5;
        if (/\b(2020|2021|2022|2023|2024)\b/i.test(notes)) score += 8;
        if (/\b(price|pricing|tax|law|rule|rate|benchmark|ranking|best|latest|current|AI|software|tool|platform)\b/i.test(notes)) score += 6;

        score = Math.min(100, Math.max(0, Math.round(score)));

        return {
          score: score,
          age: age,
          gaps: gaps,
          result: classify(score)
        };
      }

      function setReasons(reasons) {
        while (els.reasons.firstChild) {
          els.reasons.removeChild(els.reasons.firstChild);
        }

        reasons.forEach(function (reason) {
          var li = document.createElement("li");
          li.textContent = reason;
          els.reasons.appendChild(li);
        });
      }

      function briefText(calc) {
        var title = els.title.value.trim() || "Untitled article";
        var dateText = els.lastDate.value || "No visible update date entered";
        var notes = els.notes.value.trim() || "No rough notes entered.";
        var gapNames = calc.gaps.map(function (gap) { return gap.name; });
        var ageText = calc.age === null ? "unknown age" : calc.age + " months old";

        var priority;
        if (calc.score >= 70) {
          priority = "Full freshness rewrite. Re-check source base, rebuild stale sections, update examples, and add current FAQs.";
        } else if (calc.score >= 42) {
          priority = "Targeted refresh. Update dated claims, replace weak sources, and improve FAQ coverage before republishing.";
        } else if (calc.score >= 18) {
          priority = "Light refresh. Add visible update date, verify a few claims, and patch obvious FAQ gaps.";
        } else {
          priority = "Monitor only. No major rewrite signal from current checks.";
        }

        return [
          "Freshness Rewrite Brief",
          "",
          "Article: " + title,
          "Last published/updated: " + dateText,
          "Estimated age: " + ageText,
          "Topic sensitivity: " + topicLabel(els.topicType.value),
          "Risk result: " + calc.result.label + " (" + calc.score + "/100)",
          "",
          "Recommended action:",
          priority,
          "",
          "Marked gaps:",
          gapNames.length ? "- " + gapNames.join("\n- ") : "- None marked",
          "",
          "Rewrite priorities:",
          "- Verify all dated claims, stats, screenshots, prices, tool names, rules, and rankings.",
          "- Replace weak or old sources with current primary sources where possible.",
          "- Add or update a visible published/updated date if the article earns it.",
          "- Add FAQs that answer current-year, objection, comparison, cost, and next-step questions.",
          "- Rewrite the intro if it promises outdated information or old search intent.",
          "- Add an editor note only when important facts changed since the prior version.",
          "",
          "Notes to use during rewrite:",
          notes,
          "",
          "Republish checklist:",
          "- Current sources checked",
          "- Stale examples replaced",
          "- FAQ gaps filled",
          "- Title/meta aligned with refreshed angle",
          "- Internal links checked",
          "- Brief human review completed"
        ].join("\n");
      }

      function render() {
        var calc = calculate();
        var reasons = buildReasons(calc.score, calc.age, calc.gaps);

        els.riskLabel.textContent = calc.result.label;
        els.riskScore.textContent = calc.score + " / 100";
        els.riskBar.style.width = calc.score + "%";
        els.riskBar.style.background = calc.result.color;
        setReasons(reasons);

        els.brief.value = briefText(calc);
      }

      function collectState() {
        return {
          title: els.title.value,
          lastDate: els.lastDate.value,
          topicType: els.topicType.value,
          notes: els.notes.value,
          gaps: els.gaps.map(function (box) { return box.checked; })
        };
      }

      function applyState(state) {
        if (!state) return;
        els.title.value = state.title || "";
        els.lastDate.value = state.lastDate || "";
        els.topicType.value = state.topicType || "evergreen";
        els.notes.value = state.notes || "";
        if (Array.isArray(state.gaps)) {
          els.gaps.forEach(function (box, index) {
            box.checked = Boolean(state.gaps[index]);
          });
        }
      }

      function saveLocal(silent) {
        try {
          localStorage.setItem(storageKey, JSON.stringify(collectState()));
          if (!silent) setStatus("Saved on this device.");
        } catch (err) {
          setStatus("Could not save locally in this browser.");
        }
      }

      function loadLocal() {
        try {
          var raw = localStorage.getItem(storageKey);
          if (raw) applyState(JSON.parse(raw));
        } catch (err) {
          setStatus("Could not load saved draft.");
        }
      }

      function setStatus(message) {
        els.status.textContent = message;
        window.clearTimeout(setStatus.timer);
        setStatus.timer = window.setTimeout(function () {
          els.status.textContent = "";
        }, 2800);
      }

      function copyBrief() {
        els.brief.select();
        els.brief.setSelectionRange(0, els.brief.value.length);

        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(els.brief.value)
            .then(function () { setStatus("Brief copied."); })
            .catch(function () {
              fallbackCopy();
            });
        } else {
          fallbackCopy();
        }
      }

      function fallbackCopy() {
        try {
          document.execCommand("copy");
          setStatus("Brief copied.");
        } catch (err) {
          setStatus("Copy failed. Select the brief and copy manually.");
        }
      }

      function safeFileName(text) {
        var base = text.trim().toLowerCase()
          .replace(/[^a-z0-9]+/g, "-")
          .replace(/^-+|-+$/g, "")
          .slice(0, 48);
        return (base || "freshness-rewrite-brief") + ".txt";
      }

      function downloadBrief() {
        var blob = new Blob([els.brief.value], { type: "text/plain;charset=utf-8" });
        var url = URL.createObjectURL(blob);
        var a = document.createElement("a");
        a.href = url;
        a.download = safeFileName(els.title.value);
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        setStatus("Download started.");
      }

      function clearAll() {
        els.title.value = "";
        els.lastDate.value = "";
        els.topicType.value = "evergreen";
        els.notes.value = "";
        els.gaps.forEach(function (box) { box.checked = false; });
        try {
          localStorage.removeItem(storageKey);
        } catch (err) {}
        render();
        setStatus("Cleared.");
      }

      function bind() {
        [els.title, els.lastDate, els.topicType, els.notes].forEach(function (el) {
          el.addEventListener("input", function () {
            render();
            saveLocal(true);
          });
          el.addEventListener("change", function () {
            render();
            saveLocal(true);
          });
        });

        els.gaps.forEach(function (box) {
          box.addEventListener("change", function () {
            render();
            saveLocal(true);
          });
        });

        els.copyBtn.addEventListener("click", copyBrief);
        els.downloadBtn.addEventListener("click", downloadBrief);
        els.saveBtn.addEventListener("click", function () { saveLocal(false); });
        els.clearBtn.addEventListener("click", clearAll);
      }

      loadLocal();
      bind();
      render();
    }());
  </script>
</body>
</html>
