          "",
          "Marked gaps:",
          gapNames.length ? "- " + gapNames.join("\n- ") : "- None marked",
          "",
          "Rewrite priorities:",
          "- Verify dated claims, stats, screenshots, prices, tool names, rules, and rankings.",
          "- Replace weak or old sources with current primary sources where possible.",
          "- Add or update a visible published/updated date only when the article earns it.",
          "- Add FAQs that answer current-year, objection, comparison, cost, and next-step questions.",
          "- Rewrite the intro if it promises outdated information or old search intent.",
          "- Add an editor note only when important facts changed since the prior version.",
          "",
          "Notes to use during rewrite:",
          notes,
          "",
          "Republish checklist:",
          "- Current sources checked",
          "- Stale examples replaced",
          "- FAQ gaps filled",
          "- Title/meta aligned with refreshed angle",
          "- Internal links checked",
          "- Human review completed"
        ].join("\n");
      }

      function render() {
        var calc = calculate();
        var reasons = buildReasons(calc.score, calc.age, calc.gaps);

        els.riskLabel.textContent = calc.result.label;
        els.riskScore.textContent = calc.score + " / 100";
        els.riskBar.style.width = calc.score + "%";
        els.riskBar.style.background = calc.result.color;

        setReasons(reasons);

        els.brief.value = briefText(calc);
      }

      function collectState() {
        return {
          title: els.title.value,
          lastDate: els.lastDate.value,
          topicType: els.topicType.value,
          notes: els.notes.value,
          gaps: els.gaps.map(function (box) {
            return box.checked;
          })
        };
      }

      function applyState(state) {
        if (!state) return;

        els.title.value = state.title || "";
        els.lastDate.value = state.lastDate || "";
        els.topicType.value = state.topicType || "evergreen";
        els.notes.value = state.notes || "";

        if (Array.isArray(state.gaps)) {
          els.gaps.forEach(function (box, index) {
            box.checked = Boolean(state.gaps[index]);
          });
        }
      }

      function setStatus(message) {
        els.status.textContent = message;

        window.clearTimeout(setStatus.timer);
        setStatus.timer = window.setTimeout(function () {
          els.status.textContent = "";
        }, 2800);
      }

      function saveLocal(silent) {
        try {
          localStorage.setItem(storageKey, JSON.stringify(collectState()));
          if (!silent) setStatus("Saved on this device.");
        } catch (err) {
          setStatus("Could not save locally in this browser.");
        }
      }

      function loadLocal() {
        try {
          var raw = localStorage.getItem(storageKey);
          if (raw) applyState(JSON.parse(raw));
        } catch (err) {
          setStatus("Could not load saved draft.");
        }
      }

      function fallbackCopy() {
        els.brief.focus();
        els.brief.select();
        els.brief.setSelectionRange(0, els.brief.value.length);

        try {
          document.execCommand("copy");
          setStatus("Brief copied.");
        } catch (err) {
          setStatus("Copy failed. Select the brief and copy manually.");
        }
      }

      function copyBrief() {
        els.brief.focus();
        els.brief.select();
        els.brief.setSelectionRange(0, els.brief.value.length);

        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(els.brief.value)
            .then(function () {
              setStatus("Brief copied.");
            })
            .catch(function () {
              fallbackCopy();
            });
        } else {
          fallbackCopy();
        }
      }

      function safeFileName(text) {
        var base = text.trim().toLowerCase()
          .replace(/[^a-z0-9]+/g, "-")
          .replace(/^-+|-+$/g, "")
          .slice(0, 48);

        return (base || "freshness-rewrite-brief") + ".txt";
      }

      function downloadBrief() {
        var blob = new Blob([els.brief.value], {
          type: "text/plain;charset=utf-8"
        });

        var url = URL.createObjectURL(blob);
        var a = document.createElement("a");

        a.href = url;
        a.download = safeFileName(els.title.value);

        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);

        URL.revokeObjectURL(url);
        setStatus("Download started.");
      }

      function clearAll() {
        els.title.value = "";
        els.lastDate.value = "";
        els.topicType.value = "evergreen";
        els.notes.value = "";

        els.gaps.forEach(function (box) {
          box.checked = false;
        });

        try {
          localStorage.removeItem(storageKey);
        } catch (err) {}

        render();
        setStatus("Cleared.");
      }

      function bind() {
        [els.title, els.lastDate, els.topicType, els.notes].forEach(function (el) {
          el.addEventListener("input", function () {
            render();
            saveLocal(true);
          });

          el.addEventListener("change", function () {
            render();
            saveLocal(true);
          });
        });

        els.gaps.forEach(function (box) {
          box.addEventListener("change", function () {
            render();
            saveLocal(true);
          });
        });

        els.copyBtn.addEventListener("click", copyBrief);
        els.downloadBtn.addEventListener("click", downloadBrief);
        els.saveBtn.addEventListener("click", function () {
          saveLocal(false);
        });
        els.clearBtn.addEventListener("click", clearAll);
      }

      loadLocal();
      bind();
      render();
    }());
  </script>
</body>
</html>
